#!/usr/bin/env python3
"""FS3 v212 - repair: pace of the demo, AI flight and fire, no wall (Silvio, 10.10.2026).

    Pace       As the 2.5D demo (TEMPO_K 1.6): small craft and rounds; the
               FS ratios between ships and between weapons stay. Test
               switches in the address: &tempo=1.2 (whole pace), &ekk=0.7
               (speed of enemy rounds).
    Rounds     None slower than the ships (PROJ_MIN = 1.1 x the fastest
               small craft); a raised one keeps its FS reach.
    AI flight  88 % of the FS speed, turns like the demo (3.2 rad/s for the
               Myrmidon, others after their FS pitch rotation time), and
               slides through its turns (path follows the nose, ~1/3 s).
    AI fire    Only with the nose within 0.12 rad of the target, from at
               most about half the screen (as the demo).
    Wall       Fighters and bombers are no longer held inside the old
               mission band (clampToField); they follow anywhere.
    Target     The model in the bar's target view keeps one size.

Needs v211. Edits src/10_core.js, 30_waves.js, 40_world.js, 50_combat.js,
55_arms.js, 56_banks.js, 57_turrets.js, 60_effects.js, 70_ui.js,
72_target.js. Run assemble.py 212 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/72_target.js"):
    sys.exit("Abbruch: erst v211 einspielen.")
_c = open("src/10_core.js", encoding="utf-8").read()
if "const TEMPO_K = 1.6*urlNum(" in _c:
    sys.exit("v212 ist schon eingespielt.")
if "const TEMPO_K = 2;" not in _c:
    sys.exit("Abbruch: erst v211 einspielen.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
